using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.Hosting;

namespace Warehouse.Tests;

[TestClass]
public class ApiTests
{
    private static string? _db;
    private static WebApplicationFactory<Program> _factory = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        _db = Path.Combine(Path.GetTempPath(), $"wh-{Guid.NewGuid():N}.db");
        _factory = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
            b.UseSetting("ConnectionStrings:Warehouse", $"Data Source={_db}"));
    }

    [ClassCleanup]
    public static void Done()
    {
        _factory.Dispose();
        Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();
        if (_db != null) File.Delete(_db);
    }

    private static async Task<JsonElement> Json(HttpResponseMessage r) =>
        (await r.Content.ReadFromJsonAsync<JsonElement>());

    private static async Task<Guid> NewSupplier(HttpClient c, string? name = null)
    {
        var r = await c.PostAsJsonAsync("/suppliers", new { name = name ?? "S" + Guid.NewGuid().ToString("N"), email = "a@b.c" });
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        return (await Json(r)).GetProperty("id").GetGuid();
    }

    private static object Prod(Guid sup, string? sku = null, int stock = 5, int reorder = 5, int status = 0) =>
        new { sku = sku ?? Guid.NewGuid().ToString("N")[..20], name = "P", stock, reorderLevel = reorder, status, supplierId = sup };

    [TestMethod]
    public async Task SupplierRoundTrip()
    {
        var c = _factory.CreateClient();
        var id = await NewSupplier(c);
        Assert.AreEqual(HttpStatusCode.OK, (await c.GetAsync($"/suppliers/{id}")).StatusCode);
        var put = await c.PutAsJsonAsync($"/suppliers/{id}", new { name = "Renamed" + id.ToString("N"), email = (string?)null });
        Assert.AreEqual(HttpStatusCode.OK, put.StatusCode);
        var all = await Json(await c.GetAsync("/suppliers"));
        Assert.AreEqual(JsonValueKind.Array, all.ValueKind);
        Assert.AreEqual(HttpStatusCode.NoContent, (await c.DeleteAsync($"/suppliers/{id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/suppliers/{id}")).StatusCode);
    }

    [TestMethod]
    public async Task SupplierValidationAndConflict()
    {
        var c = _factory.CreateClient();
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/suppliers", new { name = "" })).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/suppliers", new { name = new string('x', 101) })).StatusCode);
        var name = "Dup" + Guid.NewGuid().ToString("N");
        await NewSupplier(c, name);
        Assert.AreEqual(HttpStatusCode.Conflict, (await c.PostAsJsonAsync("/suppliers", new { name })).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/suppliers/{Guid.NewGuid()}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.DeleteAsync($"/suppliers/{Guid.NewGuid()}")).StatusCode);
    }

    [TestMethod]
    public async Task ProductRoundTripAndSupplierIncludesProducts()
    {
        var c = _factory.CreateClient();
        var sup = await NewSupplier(c);
        var r = await c.PostAsJsonAsync("/products", Prod(sup));
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        var p = await Json(r);
        var id = p.GetProperty("id").GetGuid();
        Assert.AreEqual(sup, p.GetProperty("supplierId").GetGuid());
        Assert.AreEqual(0, p.GetProperty("status").GetInt32());

        var s = await Json(await c.GetAsync($"/suppliers/{sup}"));
        Assert.AreEqual(1, s.GetProperty("products").GetArrayLength());

        var put = await c.PutAsJsonAsync($"/products/{id}", Prod(sup, stock: 50, reorder: 1));
        Assert.AreEqual(HttpStatusCode.OK, put.StatusCode);
        Assert.AreEqual(50, (await Json(put)).GetProperty("stock").GetInt32());
        Assert.AreEqual(HttpStatusCode.OK, (await c.GetAsync("/products")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NoContent, (await c.DeleteAsync($"/products/{id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await c.GetAsync($"/products/{id}")).StatusCode);
    }

    [DataTestMethod]
    [DataRow(0, 5, 5, true)]
    [DataRow(0, 4, 5, true)]
    [DataRow(0, 6, 5, false)]
    [DataRow(1, 0, 5, false)]
    public async Task NeedsReorder(int status, int stock, int reorder, bool expected)
    {
        var c = _factory.CreateClient();
        var sup = await NewSupplier(c);
        var r = await c.PostAsJsonAsync("/products", Prod(sup, stock: stock, reorder: reorder, status: status));
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        Assert.AreEqual(expected, (await Json(r)).GetProperty("needsReorder").GetBoolean());
    }

    [TestMethod]
    public async Task ProductValidation()
    {
        var c = _factory.CreateClient();
        var sup = await NewSupplier(c);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", Prod(sup, stock: -1))).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", Prod(sup, reorder: -1))).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", Prod(sup, status: 7))).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", Prod(Guid.NewGuid()))).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/products", Prod(sup, sku: new string('x', 21)))).StatusCode);
    }

    [TestMethod]
    public async Task DuplicateSkuConflicts()
    {
        var c = _factory.CreateClient();
        var sup = await NewSupplier(c);
        var sku = Guid.NewGuid().ToString("N")[..20];
        Assert.AreEqual(HttpStatusCode.Created, (await c.PostAsJsonAsync("/products", Prod(sup, sku))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Conflict, (await c.PostAsJsonAsync("/products", Prod(sup, sku))).StatusCode);
    }
}
